import math
from fractions import Fraction

def solve_quadratic(A, B, C):
    """Solves Ax^2 + Bx + C = 0 for positive rational roots."""
    if A == 0:
        # Linear equation: Bx + C = 0
        if B == 0:
            return [] if C != 0 else [Fraction(1)] # If 0=0, all p are solutions, but we need specific roots. We skip this trivial case.
        p = Fraction(-C, B)
        return [p] if p > 0 else []

    # Quadratic equation
    delta = B**2 - 4 * A * C

    if delta < 0:
        return []

    # Check if delta is a perfect square
    sqrt_delta_float = math.sqrt(delta)
    sqrt_delta_int = int(round(sqrt_delta_float))

    if sqrt_delta_int * sqrt_delta_int != delta:
        return [] # Roots are irrational

    sqrt_delta = Fraction(sqrt_delta_int)

    # Roots are (-B +/- sqrt(delta)) / (2A)
    root1 = Fraction(-B + sqrt_delta) / (2 * A)
    root2 = Fraction(-B - sqrt_delta) / (2 * A)

    solutions = set()
    if root1 > 0:
        solutions.add(root1)
    if root2 > 0:
        solutions.add(root2)

    return list(solutions)

# Define coefficient range
D_range = [-2, -1, 0, 1, 2]
all_solutions = set()

for D3 in D_range:
    for D2 in D_range:
        for D1 in D_range:

            # Skip the trivial case where all coefficients are zero
            if D3 == 0 and D2 == 0 and D1 == 0:
                continue

            solutions = solve_quadratic(D3, D2, D1)
            for p in solutions:
                all_solutions.add(p)

# Convert set to list of unique rational numbers
final_solutions = sorted([p for p in all_solutions])

print("Unique positive rational solutions found:")
for p in final_solutions:
    print(p)
